// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

/**
 * @title LearningMemory
 * @notice Stores learning progress, completed lessons, and knowledge permanently on-chain
 * @dev Each soul's learning journey is immutably recorded
 */
contract LearningMemory is AccessControl, ReentrancyGuard {
    bytes32 public constant AGENT_ROLE = keccak256("AGENT_ROLE");

    struct LearningModule {
        string title;
        string topic;
        string difficulty; // "beginner", "intermediate", "advanced"
        uint256 completedAt;
        uint256 timeSpent; // in seconds
        bytes32 contentHash; // IPFS hash of lesson content
        uint256 score; // 0-100
    }

    struct LearningNote {
        string content;
        string[] tags;
        uint256 createdAt;
        bytes32 moduleId;
    }

    struct KnowledgeNode {
        string concept;
        uint256 understanding; // 0-100 proficiency
        uint256 lastPracticed;
        uint256 timesReviewed;
        string[] relatedConcepts;
    }

    struct LearningStats {
        uint256 totalModulesCompleted;
        uint256 totalTimeSpent;
        uint256 currentLevel;
        uint256 experiencePoints;
        uint256 longestStreak;
        uint256 currentStreak;
        uint256 lastActivityDate;
    }

    // Agent address => Learning data
    mapping(address => LearningModule[]) public learningHistory;
    mapping(address => LearningNote[]) public notes;
    mapping(address => mapping(bytes32 => KnowledgeNode)) public knowledgeGraph;
    mapping(address => bytes32[]) public knowledgeKeys;
    mapping(address => LearningStats) public stats;

    // Events
    event ModuleCompleted(
        address indexed agent,
        string title,
        string topic,
        string difficulty,
        uint256 score,
        uint256 timeSpent
    );

    event NoteAdded(
        address indexed agent,
        string content,
        bytes32 moduleId,
        uint256 timestamp
    );

    event KnowledgeUpdated(
        address indexed agent,
        string concept,
        uint256 understanding,
        uint256 timesReviewed
    );

    event LevelUp(
        address indexed agent,
        uint256 newLevel,
        uint256 experiencePoints
    );

    event StreakUpdated(
        address indexed agent,
        uint256 currentStreak,
        uint256 longestStreak
    );

    constructor() {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
    }

    /**
     * @notice Record completed learning module
     */
    function recordModule(
        address agent,
        string memory title,
        string memory topic,
        string memory difficulty,
        uint256 timeSpent,
        bytes32 contentHash,
        uint256 score
    ) external onlyRole(AGENT_ROLE) nonReentrant {
        require(agent != address(0), "Invalid agent");
        require(score <= 100, "Invalid score");

        LearningModule memory module = LearningModule({
            title: title,
            topic: topic,
            difficulty: difficulty,
            completedAt: block.timestamp,
            timeSpent: timeSpent,
            contentHash: contentHash,
            score: score
        });

        learningHistory[agent].push(module);

        // Update stats
        LearningStats storage agentStats = stats[agent];
        agentStats.totalModulesCompleted++;
        agentStats.totalTimeSpent += timeSpent;

        // Award experience points
        uint256 xp = calculateXP(difficulty, score);
        agentStats.experiencePoints += xp;

        // Check for level up
        uint256 newLevel = calculateLevel(agentStats.experiencePoints);
        if (newLevel > agentStats.currentLevel) {
            agentStats.currentLevel = newLevel;
            emit LevelUp(agent, newLevel, agentStats.experiencePoints);
        }

        // Update streak
        updateStreak(agent);

        emit ModuleCompleted(agent, title, topic, difficulty, score, timeSpent);
    }

    /**
     * @notice Add a learning note
     */
    function addNote(
        address agent,
        string memory content,
        string[] memory tags,
        bytes32 moduleId
    ) external onlyRole(AGENT_ROLE) nonReentrant {
        require(agent != address(0), "Invalid agent");

        LearningNote memory note = LearningNote({
            content: content,
            tags: tags,
            createdAt: block.timestamp,
            moduleId: moduleId
        });

        notes[agent].push(note);

        emit NoteAdded(agent, content, moduleId, block.timestamp);
    }

    /**
     * @notice Update knowledge graph with new concept or update existing
     */
    function updateKnowledge(
        address agent,
        string memory concept,
        uint256 understanding,
        string[] memory relatedConcepts
    ) external onlyRole(AGENT_ROLE) nonReentrant {
        require(agent != address(0), "Invalid agent");
        require(understanding <= 100, "Invalid understanding level");

        bytes32 conceptHash = keccak256(abi.encodePacked(concept));
        KnowledgeNode storage node = knowledgeGraph[agent][conceptHash];

        if (bytes(node.concept).length == 0) {
            // New concept
            node.concept = concept;
            knowledgeKeys[agent].push(conceptHash);
        }

        node.understanding = understanding;
        node.lastPracticed = block.timestamp;
        node.timesReviewed++;
        node.relatedConcepts = relatedConcepts;

        emit KnowledgeUpdated(agent, concept, understanding, node.timesReviewed);
    }

    /**
     * @notice Calculate XP based on difficulty and score
     */
    function calculateXP(string memory difficulty, uint256 score)
        internal
        pure
        returns (uint256)
    {
        uint256 baseXP = score; // 0-100

        bytes32 diffHash = keccak256(abi.encodePacked(difficulty));
        bytes32 beginnerHash = keccak256(abi.encodePacked("beginner"));
        bytes32 intermediateHash = keccak256(abi.encodePacked("intermediate"));
        bytes32 advancedHash = keccak256(abi.encodePacked("advanced"));

        if (diffHash == beginnerHash) {
            return baseXP * 1; // 1x multiplier
        } else if (diffHash == intermediateHash) {
            return baseXP * 2; // 2x multiplier
        } else if (diffHash == advancedHash) {
            return baseXP * 3; // 3x multiplier
        }

        return baseXP;
    }

    /**
     * @notice Calculate level from total XP
     */
    function calculateLevel(uint256 xp) internal pure returns (uint256) {
        // Level formula: sqrt(xp / 100)
        // Level 1: 100 XP, Level 2: 400 XP, Level 3: 900 XP, etc.
        if (xp < 100) return 1;
        return 1 + sqrt(xp / 100);
    }

    /**
     * @notice Update learning streak
     */
    function updateStreak(address agent) internal {
        LearningStats storage agentStats = stats[agent];

        uint256 today = block.timestamp / 1 days;
        uint256 lastActivity = agentStats.lastActivityDate / 1 days;

        if (today == lastActivity) {
            // Already counted today
            return;
        } else if (today == lastActivity + 1) {
            // Consecutive day
            agentStats.currentStreak++;
            if (agentStats.currentStreak > agentStats.longestStreak) {
                agentStats.longestStreak = agentStats.currentStreak;
            }
        } else {
            // Streak broken
            agentStats.currentStreak = 1;
        }

        agentStats.lastActivityDate = block.timestamp;

        emit StreakUpdated(agent, agentStats.currentStreak, agentStats.longestStreak);
    }

    /**
     * @notice Get learning history for agent
     */
    function getLearningHistory(address agent, uint256 limit)
        external
        view
        returns (LearningModule[] memory)
    {
        LearningModule[] memory history = learningHistory[agent];
        uint256 length = history.length;

        if (limit == 0 || limit > length) {
            limit = length;
        }

        LearningModule[] memory result = new LearningModule[](limit);
        uint256 start = length > limit ? length - limit : 0;

        for (uint256 i = 0; i < limit && start + i < length; i++) {
            result[i] = history[start + i];
        }

        return result;
    }

    /**
     * @notice Get all notes for agent
     */
    function getNotes(address agent)
        external
        view
        returns (LearningNote[] memory)
    {
        return notes[agent];
    }

    /**
     * @notice Get knowledge graph summary
     */
    function getKnowledgeSummary(address agent)
        external
        view
        returns (
            uint256 totalConcepts,
            uint256 averageUnderstanding,
            uint256 masteredConcepts
        )
    {
        bytes32[] memory keys = knowledgeKeys[agent];
        totalConcepts = keys.length;

        if (totalConcepts == 0) {
            return (0, 0, 0);
        }

        uint256 totalUnderstanding = 0;
        uint256 mastered = 0;

        for (uint256 i = 0; i < totalConcepts; i++) {
            KnowledgeNode storage node = knowledgeGraph[agent][keys[i]];
            totalUnderstanding += node.understanding;
            if (node.understanding >= 90) {
                mastered++;
            }
        }

        averageUnderstanding = totalUnderstanding / totalConcepts;
        masteredConcepts = mastered;
    }

    /**
     * @notice Get specific knowledge node
     */
    function getKnowledgeNode(address agent, string memory concept)
        external
        view
        returns (
            uint256 understanding,
            uint256 lastPracticed,
            uint256 timesReviewed,
            string[] memory relatedConcepts
        )
    {
        bytes32 conceptHash = keccak256(abi.encodePacked(concept));
        KnowledgeNode storage node = knowledgeGraph[agent][conceptHash];

        return (
            node.understanding,
            node.lastPracticed,
            node.timesReviewed,
            node.relatedConcepts
        );
    }

    /**
     * @notice Get learning statistics
     */
    function getStats(address agent)
        external
        view
        returns (LearningStats memory)
    {
        return stats[agent];
    }

    /**
     * @notice Grant agent role
     */
    function grantAgentRole(address agent)
        external
        onlyRole(DEFAULT_ADMIN_ROLE)
    {
        _grantRole(AGENT_ROLE, agent);
    }

    /**
     * @notice Square root helper (Babylonian method)
     */
    function sqrt(uint256 x) internal pure returns (uint256) {
        if (x == 0) return 0;
        uint256 z = (x + 1) / 2;
        uint256 y = x;
        while (z < y) {
            y = z;
            z = (x / z + z) / 2;
        }
        return y;
    }
}

